-- Postgres dialect of schema/0956_agent_scopes.sql (issue #653, AC-7; kept in parity with the SQLite file by
-- TestSchemaParity_SQLiteAndPostgres). Cross-tenant guard triggers become composite foreign keys
-- (tenant_id, x_id) -> (tenant_id, id); see 0001_tenancy.sql. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up

CREATE TABLE agent_scopes (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  key TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired')),
  name TEXT NOT NULL,
  doc TEXT NOT NULL,
  doc_sha256 TEXT NOT NULL,
  version BIGINT NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, key)
);

CREATE TABLE agent_scope_versions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  scope_id TEXT NOT NULL,
  version BIGINT NOT NULL,
  snapshot TEXT NOT NULL,
  actor TEXT NOT NULL,
  changed_at TEXT NOT NULL,
  policy_ref TEXT,
  UNIQUE (tenant_id, scope_id, version),
  FOREIGN KEY (tenant_id, scope_id) REFERENCES agent_scopes (tenant_id, id)
);

CREATE TRIGGER agent_scope_versions_no_update BEFORE UPDATE ON agent_scope_versions
	FOR EACH ROW EXECUTE FUNCTION tessera_abort('agent_scope_versions is append-only');

CREATE TRIGGER agent_scope_versions_no_delete BEFORE DELETE ON agent_scope_versions
	FOR EACH ROW EXECUTE FUNCTION tessera_abort('agent_scope_versions is append-only');
